const { useState } = React;

function Counter() {
  const [count, setCount] = useState(0);

  function handleClick() {
    console.log('설정 전:', count);
    setCount(count + 1);
    console.log('설정 후:', count);
  }

  return <button type="button" onClick={handleClick}>현재 값: {count}</button>;
}

ReactDOM.createRoot(document.querySelector('#root')).render(<Counter />);

